 and (p->'link'='null'::jsonb or (jsonb_typeof(p->'link')='object' and p->'link'->>'kind' in ('course','document','note') and length(p->'link'->>'id')>0 and jsonb_typeof(p->'link'->'title')='string')),false);
exception when others then return false;
end $$;

