-- 202610110014_course_workspace.sql; sha256=3443c4a1b32f6528ac19cd38e430f475bf51528901442c2d14c7e2a84343b827
create table if not exists public.course_topics (
 id uuid primary key default gen_random_uuid(),course_id uuid not null references public.courses(id) on delete cascade,
 title text not null check(length(trim(title)) between 1 and 200),description text not null default '' check(length(description)<=5000),
 position integer not null check(position between 1 and 1000),version integer not null default 1,created_at timestamptz not null default now()
);
create table if not exists public.course_topic_links (
 course_id uuid not null references public.courses(id) on delete cascade,topic_id uuid not null references public.course_topics(id) on delete cascade,
 material_id uuid references public.course_content(id) on delete cascade,assignment_id uuid references public.assignments(id) on delete cascade,
 check((material_id is null)<>(assignment_id is null)),unique(material_id),unique(assignment_id)
);
create table if not exists public.course_topic_progress (
 user_id uuid not null references public.profiles(id) on delete cascade,topic_id uuid not null references public.course_topics(id) on delete cascade,
 primary key(user_id,topic_id)
);
alter table public.course_topics enable row level security;
alter table public.course_topic_links enable row level security;
alter table public.course_topic_progress enable row level security;
revoke all on public.course_topics,public.course_topic_links,public.course_topic_progress from anon,authenticated;
create or replace function public.manage_course_workspace(c uuid) returns boolean language sql stable security definer set search_path=pg_catalog as $$
 select public.is_active_user() and public.can_view_course(c) and (public.manage_course_material(c,'lecture') or public.manage_course_material(c,'presentation') or public.manage_course_material(c,'material') or public.can_grade_course(c));
$$;
create or replace function public.course_workspace(p_course uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
declare result jsonb;
begin
 if not public.is_active_user() or not public.can_view_course(p_course) then raise exception 'Course access denied';end if;
 select jsonb_build_object(
 'topics',coalesce((select jsonb_agg(to_jsonb(t) order by t.position,t.created_at,t.id) from public.course_topics t where t.course_id=p_course),'[]'::jsonb),
 'links',coalesce((select jsonb_agg(jsonb_build_object('topic_id',l.topic_id,'source_id',coalesce(l.material_id,l.assignment_id),'source_kind',case when l.material_id is not null then 'material' else 'assignment' end)) from public.course_topic_links l where l.course_id=p_course and ((l.material_id is not null and public.read_course_material(l.material_id)) or (l.assignment_id is not null and public.can_read_assignment(l.assignment_id)))),'[]'::jsonb),
 'completed',coalesce((select jsonb_agg(p.topic_id) from public.course_topic_progress p join public.course_topics t on t.id=p.topic_id where p.user_id=auth.uid() and t.course_id=p_course),'[]'::jsonb),
 'canManage',public.manage_course_workspace(p_course),
 'resume',(select jsonb_build_object('item_id',r.item_id,'page',r.page,'total_pages',r.total_pages) from public.course_reader_states r join public.course_content i on i.id=r.item_id where r.user_id=auth.uid() and i.course_id=p_course and r.total_pages>0 and public.can_read_course_document(r.item_id) order by r.updated_at desc,r.item_id limit 1)) into result;
 return result;
end $$;
create or replace function public.save_course_topic(p_course uuid,p_title text,p_description text,p_position integer,p_id uuid default null,p_version integer default null) returns uuid language plpgsql security definer set search_path=pg_catalog as $$
declare result uuid;
begin
 if not public.manage_course_workspace(p_course) then raise exception 'Access denied';end if;
 if p_title is null or length(trim(p_title)) not between 1 and 200 or p_description is null or length(p_description)>5000 or p_position is null or p_position not between 1 and 1000 then raise exception 'Invalid topic';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_course::text,14));
 if p_id is null then
  if (select count(*) from public.course_topics where course_id=p_course)>=200 then raise exception 'Topic limit reached';end if;
  insert into public.course_topics(course_id,title,description,position) values(p_course,trim(p_title),p_description,p_position) returning id into result;
 else
  update public.course_topics set title=trim(p_title),description=p_description,position=p_position,version=version+1 where id=p_id and course_id=p_course and version=p_version returning id into result;
  if not found then raise exception 'Topic changed. Refresh before saving';end if;
 end if;
 insert into public.audit_events(actor_id,action,entity_id) values(auth.uid(),'course.topic_saved',result);
 return result;
end $$;
create or replace function public.delete_course_topic(p_id uuid,p_version integer) returns void language plpgsql security definer set search_path=pg_catalog as $$
declare c uuid;
begin
 select course_id into c from public.course_topics where id=p_id;
 if c is null or not public.manage_course_workspace(c) then raise exception 'Access denied';end if;
 perform pg_advisory_xact_lock(hashtextextended(c::text,14));
 delete from public.course_topics where id=p_id and version=p_version;
 if not found then raise exception 'Topic changed. Refresh before deleting';end if;
 insert into public.audit_events(actor_id,action,entity_id) values(auth.uid(),'course.topic_deleted',p_id);
end $$;
create or replace function public.link_course_topic(p_course uuid,p_source uuid,p_kind text,p_topic uuid) returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
 if p_kind is null or p_kind not in ('material','assignment') then raise exception 'Invalid source';end if;
 if p_kind='material' then
  if not exists(select 1 from public.course_content i where i.id=p_source and i.course_id=p_course and i.kind<>'assignment' and public.manage_course_material(p_course,i.kind)) then raise exception 'Access denied';end if;
 else
  if not public.can_grade_course(p_course) or not exists(select 1 from public.assignments a where a.id=p_source and a.course_id=p_course) then raise exception 'Access denied';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_course::text,14));
 if p_topic is not null and not exists(select 1 from public.course_topics where id=p_topic and course_id=p_course) then raise exception 'Topic belongs to another course';end if;
 delete from public.course_topic_links where (p_kind='material' and material_id=p_source) or (p_kind='assignment' and assignment_id=p_source);
 if p_topic is not null then insert into public.course_topic_links(course_id,topic_id,material_id,assignment_id) values(p_course,p_topic,case when p_kind='material' then p_source end,case when p_kind='assignment' then p_source end);end if;
end $$;
create or replace function public.complete_course_topic(p_topic uuid,p_done boolean) returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
 if p_done is null or not public.is_active_user() or not exists(select 1 from public.course_topics t where t.id=p_topic and public.can_view_course(t.course_id)) then raise exception 'Access denied';end if;
 if p_done then insert into public.course_topic_progress(user_id,topic_id) values(auth.uid(),p_topic) on conflict do nothing;
 else delete from public.course_topic_progress where user_id=auth.uid() and topic_id=p_topic;end if;
end $$;
do $$ declare f record; begin
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('manage_course_workspace','course_workspace','save_course_topic','delete_course_topic','link_course_topic','complete_course_topic') loop
 execute format('revoke all on function %s from public,anon,authenticated',f.signature);
 execute format('grant execute on function %s to authenticated',f.signature);
 end loop;
end $$;
notify pgrst,'reload schema';

-- 202610110015_leader_roster.sql; sha256=9fa636807f9129b897544c719358a988eda333e96def7730c9cc92245ff6d76b
-- Scoped roster: a leader may read names and roles only for their own active group.
-- No private notes, submissions, email addresses or global profile access are granted.

create or replace function public.group_member_catalog(p_group uuid,p_offset integer default 0)
returns table(user_id uuid,full_name text,role public.group_role,active boolean)
language plpgsql stable security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() or not (public.is_owner() or public.is_group_leader(p_group)) then
  raise exception 'Group leader required' using errcode='42501';
 end if;
 if p_offset is null or p_offset<0 then raise exception 'Invalid offset'; end if;
 return query select m.user_id,p.full_name,m.role,m.active
 from public.group_memberships m join public.profiles p on p.id=m.user_id
 where m.group_id=p_group
 order by p.full_name,m.user_id,m.role limit 50 offset p_offset;
end;
$$;
revoke all on function public.group_member_catalog(uuid,integer) from public,anon;
grant execute on function public.group_member_catalog(uuid,integer) to authenticated;
notify pgrst,'reload schema';

-- 202610120016_registration_access.sql; sha256=44ce0c264ca8d1d4f4b2f7708d1e15d95ff475801d4a7402f3365b435a4e1e63
-- Repeatable registration access update. Existing memberships are preserved.
create table if not exists public.group_access_requests(
 user_id uuid primary key references public.profiles(id),
 group_id uuid not null references public.study_groups(id),
 status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')),
 created_at timestamptz not null default now()
);
alter table public.group_access_requests enable row level security;
alter table public.group_access_requests drop constraint if exists group_access_requests_status_check;
alter table public.group_access_requests add constraint group_access_requests_status_check check(status in ('pending','approved','rejected','cancelled'));
revoke all on public.group_access_requests from anon,authenticated;
create or replace function public.request_group_access(p_group uuid) returns void
language plpgsql security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() or not exists(select 1 from public.study_groups where id=p_group and not blocked) then raise exception 'Group unavailable';end if;
 perform 1 from public.profiles where id=auth.uid() for update;
 if exists(select 1 from public.group_access_requests where user_id=auth.uid() and status='pending' and group_id<>p_group) then raise exception 'A request is already pending';end if;
 if exists(select 1 from public.group_memberships where user_id=auth.uid() and active) then raise exception 'Use owner to change existing membership';end if;
 if exists(select 1 from public.group_memberships where user_id=auth.uid() and group_id=p_group and not active) then raise exception 'Membership disabled';end if;
 insert into public.group_access_requests(user_id,group_id) values(auth.uid(),p_group)
 on conflict(user_id) do update set group_id=excluded.group_id,status='pending',created_at=now()
 where public.group_access_requests.status<>'pending';
end $$;
create or replace function public.join_group(p_group uuid) returns void language sql security definer set search_path=pg_catalog as $$select public.request_group_access(p_group)$$;
create or replace function public.group_request_catalog(p_group uuid default null,p_offset integer default 0)
returns table(user_id uuid,group_id uuid,full_name text,status text,created_at timestamptz)
language plpgsql stable security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() or p_offset<0 then raise exception 'Unavailable';end if;
 if p_group is not null and not (public.is_owner() or public.is_group_leader(p_group)) then raise exception 'No rights';end if;
 return query select r.user_id,r.group_id,p.full_name,r.status,r.created_at from public.group_access_requests r join public.profiles p on p.id=r.user_id
 where (p_group is null and r.user_id=auth.uid()) or (r.group_id=p_group and r.status='pending' and not p.blocked and not exists(select 1 from public.group_memberships m where m.user_id=r.user_id and m.active))
 order by r.created_at,r.user_id limit 50 offset p_offset;
end $$;
create or replace function public.resolve_group_request(p_user uuid,p_group uuid,p_approve boolean) returns void
language plpgsql security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() or not (public.is_owner() or public.is_group_leader(p_group)) or not exists(select 1 from public.study_groups where id=p_group and not blocked) then raise exception 'No rights';end if;
 -- Lock the account to serialize competing approvals, transfers and blocks.
 perform 1 from public.profiles where id=p_user and not blocked for update;
 if not found then raise exception 'Account unavailable';end if;
 perform 1 from public.group_access_requests where user_id=p_user and group_id=p_group and status='pending' for update;
 if not found then raise exception 'Request unavailable';end if;
 if p_approve then
  if exists(select 1 from public.group_memberships where user_id=p_user and active) then raise exception 'Account already has membership';end if;
  if exists(select 1 from public.group_memberships where user_id=p_user and group_id=p_group and not active) then raise exception 'Membership disabled';end if;
  insert into public.group_memberships(user_id,group_id,role) values(p_user,p_group,'student');
 end if;
 update public.group_access_requests set status=case when p_approve then 'approved' else 'rejected' end where user_id=p_user;
 insert into public.audit_events(actor_id,action,entity_id,details) values(auth.uid(),'student.request_resolved',p_user,jsonb_build_object('group_id',p_group,'approved',p_approve));
end $$;
revoke all on function public.request_group_access(uuid),public.join_group(uuid),public.group_request_catalog(uuid,integer),public.resolve_group_request(uuid,uuid,boolean) from public,anon;
grant execute on function public.request_group_access(uuid),public.join_group(uuid),public.group_request_catalog(uuid,integer),public.resolve_group_request(uuid,uuid,boolean) to authenticated;

create or replace function public.has_section_access(s text,g uuid default null,c uuid default null) returns boolean
language sql stable security definer set search_path=pg_catalog as $$
 select public.is_active_user() and (public.is_owner() or (
 (g is null or public.is_group_member(g)) and
 -- New accounts may read the shared library; suspended memberships remain restricted.
 (g is not null or (s='library' and not exists(select 1 from public.group_memberships where user_id=auth.uid())) or exists(select 1 from public.group_memberships m where m.user_id=auth.uid() and m.active and public.is_group_member(m.group_id))) and
 not exists(select 1 from public.access_denials d where
 (d.user_id=auth.uid() or d.group_id=g or (g is null and d.group_id in (
 select group_id from public.group_memberships where user_id=auth.uid() and active)))
 and (d.section=s or (c is not null and d.section='course' and d.course_id=c)))
 ));
$$;

create or replace function public.cancel_group_request() returns void
language plpgsql security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() then raise exception 'Unavailable';end if;
 perform 1 from public.profiles where id=auth.uid() for update;
 update public.group_access_requests set status='cancelled' where user_id=auth.uid() and status='pending';
end $$;
revoke all on function public.cancel_group_request() from public,anon;
grant execute on function public.cancel_group_request() to authenticated;

-- 202610120017_section_notifications.sql; sha256=f226975abdfa269c6683f18c438c8a2016c1efe9018c636478254efca5bad4b7
create table if not exists public.announcement_reads(
 user_id uuid not null references public.profiles(id),
 announcement_id uuid not null references public.group_board(id) on delete cascade,
 read_at timestamptz not null default now(),
 primary key(user_id,announcement_id)
);
alter table public.announcement_reads enable row level security;
revoke all on public.announcement_reads from anon,authenticated;
create or replace function public.section_notification_counts() returns jsonb
language plpgsql stable security definer set search_path=pg_catalog as $$
declare announcements bigint;overdue bigint;
begin
 if not public.is_active_user() then raise exception 'Account unavailable';end if;
 if public.is_owner() then return jsonb_build_object('user_id',auth.uid(),'announcements',0,'overdue',0);end if;
 select count(*) into announcements from public.group_board b
 where b.kind='announcement' and b.author_id<>auth.uid()
 and public.read_group_board(b.group_id,b.course_id,b.kind)
 and not exists(select 1 from public.announcement_reads r where r.user_id=auth.uid() and r.announcement_id=b.id);
 select count(*) into overdue from public.assignments a
 where a.due_at<now() and public.can_submit_assignment(a.id)
 and coalesce((select s.status from public.submissions s where s.assignment_id=a.id and s.student_id=auth.uid() order by s.attempt_no desc limit 1),'not_submitted') not in ('submitted','graded');
 return jsonb_build_object('user_id',auth.uid(),'announcements',announcements,'overdue',overdue);
end $$;
create or replace function public.unread_announcements(p_ids uuid[]) returns uuid[]
language plpgsql stable security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() or p_ids is null or cardinality(p_ids)>50 then raise exception 'Unavailable';end if;
 return array(select b.id from public.group_board b where b.id=any(p_ids) and b.kind='announcement' and b.author_id<>auth.uid()
 and public.read_group_board(b.group_id,b.course_id,b.kind)
 and not exists(select 1 from public.announcement_reads r where r.user_id=auth.uid() and r.announcement_id=b.id));
end $$;
create or replace function public.mark_announcement_read(p_id uuid) returns void
language plpgsql security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() or not exists(select 1 from public.group_board b where b.id=p_id and b.kind='announcement' and public.read_group_board(b.group_id,b.course_id,b.kind)) then raise exception 'Announcement unavailable';end if;
 insert into public.announcement_reads(user_id,announcement_id) values(auth.uid(),p_id) on conflict do nothing;
end $$;
revoke all on function public.section_notification_counts(),public.unread_announcements(uuid[]),public.mark_announcement_read(uuid) from public,anon;
grant execute on function public.section_notification_counts(),public.unread_announcements(uuid[]),public.mark_announcement_read(uuid) to authenticated;

-- 202610140018_teacher_workspace.sql; sha256=cffa55b866fd20cdaadf9368ddf353fbb5e09ffabbe40e149b168e51ddcb68d9
create or replace function public.active_teaching_course(c uuid) returns boolean language sql stable security definer set search_path=pg_catalog as $$
 select public.is_active_user() and exists(select 1 from public.teaching_assignments t join public.group_memberships m on m.group_id=t.group_id and m.user_id=t.teacher_id and m.role='teacher' join public.courses x on x.id=t.course_id join public.study_groups g on g.id=x.group_id where t.teacher_id=auth.uid() and t.course_id=c and m.active and not x.archived and not g.blocked);
$$;
create or replace function public.can_grade_course(c uuid) returns boolean language sql stable security definer set search_path=pg_catalog as $$
 select public.is_owner() or (public.active_teaching_course(c) and public.can_view_course(c) and exists(select 1 from public.courses x where x.id=c and public.has_section_access('assignments',x.group_id,c)));
$$;
create or replace function public.manage_course_material(c uuid,k public.content_kind) returns boolean language sql stable security definer set search_path=pg_catalog as $$
 select public.is_owner() or (k<>'assignment' and public.can_view_course(c) and exists(select 1 from public.courses x where x.id=c and public.has_section_access(public.content_section(k),x.group_id,c) and (public.is_group_leader(x.group_id) or public.active_teaching_course(c))));
$$;
create or replace function public.write_group_board(g uuid,c uuid,k text,a uuid default null) returns boolean language sql stable security definer set search_path=pg_catalog as $$
 select public.read_group_board(g,c,k) and (public.is_owner() or public.is_group_leader(g) or (k='announcement' and c is not null and (a is null or a=auth.uid()) and public.active_teaching_course(c)));
$$;
create table if not exists public.teacher_review_history(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions(id) on delete cascade,actor_id uuid not null references public.profiles(id),action text not null check(action in ('draft','publish','return')),score numeric,previous_score numeric,previous_published boolean not null default false,created_at timestamptz not null default clock_timestamp());
alter table public.teacher_review_history enable row level security;
revoke all on public.teacher_review_history from public,anon,authenticated;
create index if not exists teacher_history_by_work on public.teacher_review_history(submission_id,created_at desc);
drop policy if exists grades_read on public.grades;
create policy grades_read on public.grades for select to authenticated using(exists(select 1 from public.submissions s join public.assignments a on a.id=s.assignment_id where s.id=submission_id and public.can_read_submission(s.id) and (public.is_owner() or public.can_grade_course(a.course_id) and s.student_id<>auth.uid() or s.student_id=auth.uid() and released_at is not null)));
alter table public.submissions add column if not exists assignment_snapshot jsonb;
create or replace function public.capture_assignment_snapshot() returns trigger language plpgsql security definer set search_path=pg_catalog as $$begin select to_jsonb(a) into new.assignment_snapshot from public.assignments a where a.id=new.assignment_id;return new;end $$;
drop trigger if exists submission_assignment_snapshot on public.submissions;
create trigger submission_assignment_snapshot before insert on public.submissions for each row execute function public.capture_assignment_snapshot();
alter table public.submissions add column if not exists review_version integer not null default 1;
alter table public.assignments add column if not exists revision integer not null default 1;
create or replace function public.bump_review_version() returns trigger language plpgsql set search_path=pg_catalog as $$begin new.review_version:=old.review_version+1;return new;end $$;
drop trigger if exists submissions_review_version on public.submissions;
create trigger submissions_review_version before update on public.submissions for each row execute function public.bump_review_version();
create or replace function public.bump_assignment_revision() returns trigger language plpgsql set search_path=pg_catalog as $$begin new.revision:=old.revision+1;return new;end $$;
drop trigger if exists assignments_revision on public.assignments;
create trigger assignments_revision before update on public.assignments for each row execute function public.bump_assignment_revision();
create or replace function public.teacher_catalog() returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() then raise exception 'Account unavailable';end if;
 return coalesce((select jsonb_agg(to_jsonb(q) order by q.title,q.group_name,q.id) from (
 select c.id,c.group_id,c.title,c.archived,g.name as group_name,public.can_grade_course(c.id) as can_grade,
 case when public.can_grade_course(c.id) then (select count(*) from public.assignments a where a.course_id=c.id) end as assignment_count,
 case when public.can_grade_course(c.id) then (select count(*) from (select distinct on (s.assignment_id,s.student_id) s.status,s.student_id from public.submissions s join public.assignments a on a.id=s.assignment_id where a.course_id=c.id order by s.assignment_id,s.student_id,s.attempt_no desc) w where w.status='submitted' and w.student_id<>auth.uid()) end as pending,
 case when public.can_grade_course(c.id) then (select count(*) from (select distinct on (s.assignment_id,s.student_id) s.id,s.status,s.student_id from public.submissions s join public.assignments a on a.id=s.assignment_id where a.course_id=c.id order by s.assignment_id,s.student_id,s.attempt_no desc) w join public.grades r on r.submission_id=w.id where w.status='submitted' and r.released_at is null and w.student_id<>auth.uid()) end as drafts,
 case when public.can_grade_course(c.id) then (select count(distinct m.user_id) from public.group_memberships m join public.profiles p on p.id=m.user_id where m.group_id=c.group_id and m.active and m.role in ('student','leader') and not p.blocked) end as students
 from public.courses c join public.study_groups g on g.id=c.group_id where public.active_teaching_course(c.id) and public.can_view_course(c.id)
 ) q),'[]'::jsonb);
end $$;
create or replace function public.teacher_work_json(p_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
begin
 return (select to_jsonb(q) from (select s.id,s.student_id,(not p.blocked and exists(select 1 from public.group_memberships m join public.courses c on c.group_id=m.group_id where c.id=a.course_id and m.user_id=s.student_id and m.active and m.role in ('student','leader'))) as current_member,p.full_name as student_name,s.text_answer,s.attempt_no,s.status,s.submitted_at,s.is_late,s.return_feedback,s.review_version,f.storage_path,f.original_name,f.mime_type,f.size_bytes,case when s.student_id<>auth.uid() or r.released_at is not null or public.is_owner() then r.score end as score,case when s.student_id<>auth.uid() or r.released_at is not null or public.is_owner() then r.feedback end as feedback,r.released_at from public.submissions s join public.assignments a on a.id=s.assignment_id join public.profiles p on p.id=s.student_id left join public.files f on f.id=s.file_id left join public.grades r on r.submission_id=s.id where s.id=p_id and public.can_grade_course(a.course_id) and public.can_read_submission(s.id)) q);
end $$;
create or replace function public.teacher_review_queue(p_course uuid default null,p_assignment uuid default null,p_status text default 'pending',p_search text default '',p_offset integer default 0) returns jsonb
language plpgsql stable security definer set search_path=pg_catalog as $$
declare result jsonb;
begin
 if not public.is_active_user() or p_status not in ('pending','draft','graded','returned','all') or p_search is null or length(p_search)>200 or p_offset is null or p_offset<0 then raise exception 'Invalid request';end if;
 if p_course is not null and not public.can_grade_course(p_course) then raise exception 'Teacher required';end if;
 if p_assignment is not null and not exists(select 1 from public.assignments where id=p_assignment and public.can_grade_course(course_id) and (p_course is null or course_id=p_course)) then raise exception 'Assignment unavailable';end if;
 with latest as (select distinct on (s.assignment_id,s.student_id) s.* from public.submissions s join public.assignments a on a.id=s.assignment_id where public.can_grade_course(a.course_id) and s.student_id<>auth.uid() and (p_course is null or a.course_id=p_course) and (p_assignment is null or a.id=p_assignment) order by s.assignment_id,s.student_id,s.attempt_no desc),
 eligible as (select s.id,s.assignment_id,s.student_id,(not p.blocked and exists(select 1 from public.group_memberships m where m.group_id=c.group_id and m.user_id=s.student_id and m.active and m.role in ('student','leader'))) as current_member,p.full_name as student_name,s.status,s.attempt_no,s.submitted_at,s.is_late,s.review_version,r.score,r.released_at,a.title as assignment_title,a.max_score,c.id as course_id,c.title as course_title,g.name as group_name from latest s join public.assignments a on a.id=s.assignment_id join public.courses c on c.id=a.course_id join public.study_groups g on g.id=c.group_id join public.profiles p on p.id=s.student_id left join public.grades r on r.submission_id=s.id where s.status in ('submitted','graded','returned') and (p_status='all' or p_status='pending' and s.status='submitted' or p_status='draft' and s.status='submitted' and r.score is not null and r.released_at is null or p_status='graded' and s.status='graded' or p_status='returned' and s.status='returned') and (p_search='' or position(lower(p_search) in lower(p.full_name||' '||a.title||' '||c.title||' '||g.name))>0)),
 page as (select * from eligible order by submitted_at nulls last,id limit 30 offset p_offset)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by submitted_at nulls last,id) from page),'[]'::jsonb),'total',(select count(*) from eligible)) into result;
 return result;
end $$;
create or replace function public.teacher_submission_detail(p_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
declare s public.submissions%rowtype;a public.assignments%rowtype;latest uuid;history jsonb;
begin
 select * into s from public.submissions where id=p_id;select * into a from public.assignments where id=s.assignment_id;
 if not public.is_active_user() or s.id is null or not public.can_grade_course(a.course_id) or not public.can_read_submission(s.id) then raise exception 'Work unavailable';end if;
 select id into latest from public.submissions where assignment_id=s.assignment_id and student_id=s.student_id order by attempt_no desc limit 1;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.attempt_no desc),'[]') into history from (select id,attempt_no,status,submitted_at from public.submissions where assignment_id=s.assignment_id and student_id=s.student_id order by attempt_no desc limit 20) q;
 return jsonb_build_object('work',public.teacher_work_json(p_id),'assignment',coalesce(s.assignment_snapshot,to_jsonb(a)),'assignment_snapshot',s.assignment_snapshot is not null,'latest_id',latest,'can_review',s.id=latest and s.student_id<>auth.uid() and s.status in ('submitted','graded'),'history',history,'group_name',(select g.name from public.study_groups g join public.courses c on c.group_id=g.id where c.id=a.course_id),'course_title',(select title from public.courses where id=a.course_id));
end $$;
create or replace function public.teacher_assignment_roster(p_assignment uuid,p_search text default '',p_status text default 'all',p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
declare a public.assignments%rowtype;result jsonb;
begin
 select * into a from public.assignments where id=p_assignment;
 if not public.is_active_user() or a.id is null or not public.can_grade_course(a.course_id) or p_search is null or length(p_search)>200 or p_status is null or p_status not in ('all','not_submitted','submitted','returned','graded','uploading','deleting') or p_offset is null or p_offset<0 then raise exception 'Teacher required';end if;
 with students as (select distinct p.id as student_id,p.full_name as student_name from public.profiles p join public.group_memberships m on m.user_id=p.id join public.courses c on c.group_id=m.group_id where c.id=a.course_id and m.active and m.role in ('student','leader') and not p.blocked),
 eligible as (select p.*,case when s.status in ('submitted','graded','returned') or s.student_id=auth.uid() then s.id end as work_id,coalesce(s.status,'not_submitted') as status,s.attempt_no,s.submitted_at,s.is_late,case when p.student_id<>auth.uid() or r.released_at is not null or public.is_owner() then r.score end as score,r.released_at from students p left join lateral (select * from public.submissions w where w.assignment_id=p_assignment and w.student_id=p.student_id order by attempt_no desc limit 1) s on true left join public.grades r on r.submission_id=s.id where (p_search='' or position(lower(p_search) in lower(p.student_name))>0) and (p_status='all' or coalesce(s.status,'not_submitted')=p_status)),
 page as (select * from eligible order by student_name,student_id limit 30 offset p_offset)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by student_name,student_id) from page),'[]'::jsonb),'total',(select count(*) from eligible)) into result;return result;
end $$;
create or replace function public.teacher_save_assignment(p_course uuid,p_title text,p_description text,p_due timestamptz,p_max integer,p_late boolean,p_id uuid default null,p_revision integer default null) returns uuid language plpgsql security definer set search_path=pg_catalog as $$
declare a public.assignments%rowtype;
begin
 if not public.is_active_user() or not public.can_grade_course(p_course) then raise exception 'Teacher required';end if;
 if p_id is null then return public.create_assignment(p_course,p_title,p_description,p_due,p_max,p_late);end if;
 select * into a from public.assignments where id=p_id for update;
 if a.id is null or a.course_id<>p_course or p_revision is null or a.revision<>p_revision then raise exception 'Assignment changed; refresh before saving';end if;
 if p_max<>a.max_score and exists(select 1 from public.submissions where assignment_id=p_id) then raise exception 'Cannot change maximum after submissions';end if;
 update public.assignments set title=trim(p_title),description=p_description,due_at=p_due,max_score=p_max,allow_late=p_late where id=p_id;
 insert into public.audit_events(actor_id,action,entity_id) values(auth.uid(),'assignment.updated',p_id);return p_id;
end $$;
create or replace function public.teacher_review_submission(p_id uuid,p_version integer,p_action text,p_score numeric,p_feedback text) returns void language plpgsql security definer set search_path=pg_catalog as $$
declare s public.submissions%rowtype;c uuid;old_score numeric;old_published boolean;
begin
 select * into s from public.submissions where id=p_id for update;select course_id into c from public.assignments where id=s.assignment_id;
 if not public.is_active_user() or s.id is null or not public.can_grade_course(c) or s.student_id=auth.uid() then raise exception 'Teacher required; self grading unavailable';end if;
 if p_version is null or s.review_version<>p_version or exists(select 1 from public.submissions where assignment_id=s.assignment_id and student_id=s.student_id and attempt_no>s.attempt_no) then raise exception 'Work changed; refresh before saving';end if;
 if s.status='graded' and p_action='draft' then raise exception 'Published grade cannot become draft';end if;
 select score,released_at is not null into old_score,old_published from public.grades where submission_id=p_id;
 if p_feedback is null or length(p_feedback)>50000 then raise exception 'Invalid feedback';end if;
 if p_action='return' then perform public.return_submission(p_id,p_feedback);
 elsif p_action in ('draft','publish') then perform public.save_grade(p_id,p_score,p_feedback,p_action='publish');
 else raise exception 'Unknown review action';end if;
 insert into public.teacher_review_history(submission_id,actor_id,action,score,previous_score,previous_published) values(p_id,auth.uid(),p_action,case when p_action='return' then null else p_score end,old_score,coalesce(old_published,false));
end $$;
revoke execute on function public.save_grade(uuid,numeric,text,boolean),public.return_submission(uuid,text) from authenticated,anon,public;
create or replace function public.teacher_submission_history(p_id uuid,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
declare s public.submissions%rowtype;c uuid;result jsonb;
begin
 select * into s from public.submissions where id=p_id;select course_id into c from public.assignments where id=s.assignment_id;
 if not public.is_active_user() or s.id is null or not public.can_grade_course(c) or not public.can_read_submission(s.id) or p_offset is null or p_offset<0 then raise exception 'Work unavailable';end if;
 with all_attempts as (select id,attempt_no,status,submitted_at from public.submissions where assignment_id=s.assignment_id and student_id=s.student_id), page as (select * from all_attempts order by attempt_no desc limit 20 offset p_offset)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by attempt_no desc) from page),'[]'::jsonb),'total',(select count(*) from all_attempts)) into result;return result;
end $$;
revoke all on function public.teacher_submission_history(uuid,integer) from public,anon;
grant execute on function public.teacher_submission_history(uuid,integer) to authenticated;
create or replace function public.teacher_review_history_page(p_id uuid,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
declare s public.submissions%rowtype;c uuid;result jsonb;
begin
 select * into s from public.submissions where id=p_id;select course_id into c from public.assignments where id=s.assignment_id;
 if not public.is_active_user() or s.id is null or not public.can_grade_course(c) or not public.can_read_submission(s.id) or p_offset is null or p_offset<0 then raise exception 'Work unavailable';end if;
 with events as (select h.id,p.full_name as actor_name,h.action,h.score,case when s.student_id<>auth.uid() or public.is_owner() or h.previous_published then h.previous_score end as previous_score,h.created_at from public.teacher_review_history h join public.profiles p on p.id=h.actor_id where h.submission_id=p_id and (s.student_id<>auth.uid() or public.is_owner() or h.action<>'draft')),page as (select * from events order by created_at desc,id limit 20 offset p_offset)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by created_at desc,id) from page),'[]'::jsonb),'total',(select count(*) from events)) into result;return result;
end $$;
revoke all on function public.teacher_review_history_page(uuid,integer) from public,anon;
grant execute on function public.teacher_review_history_page(uuid,integer) to authenticated;
-- Helpers remain private; public RPCs always check current permissions.
revoke all on function public.teacher_work_json(uuid),public.bump_review_version(),public.bump_assignment_revision(),public.capture_assignment_snapshot() from public,anon,authenticated;
revoke all on function public.active_teaching_course(uuid),public.teacher_catalog(),public.teacher_review_queue(uuid,uuid,text,text,integer),public.teacher_submission_detail(uuid),public.teacher_assignment_roster(uuid,text,text,integer),public.teacher_save_assignment(uuid,text,text,timestamptz,integer,boolean,uuid,integer),public.teacher_review_submission(uuid,integer,text,numeric,text) from public,anon;
grant execute on function public.active_teaching_course(uuid),public.teacher_catalog(),public.teacher_review_queue(uuid,uuid,text,text,integer),public.teacher_submission_detail(uuid),public.teacher_assignment_roster(uuid,text,text,integer),public.teacher_save_assignment(uuid,text,text,timestamptz,integer,boolean,uuid,integer),public.teacher_review_submission(uuid,integer,text,numeric,text) to authenticated;
create or replace function public.work_catalog(p_assignment uuid,p_offset integer default 0)
returns table(id uuid,student_id uuid,student_name text,text_answer text,attempt_no integer,status text,submitted_at timestamptz,is_late boolean,return_feedback text,storage_path text,original_name text,mime_type text,size_bytes bigint,score numeric,feedback text,released_at timestamptz)
language plpgsql stable security definer set search_path=pg_catalog as $$
declare grader boolean;
begin
 if not public.can_read_assignment(p_assignment) then raise exception 'Access denied'; end if;
 if p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'Invalid page'; end if;
 select public.can_grade_course(a.course_id) into grader from public.assignments a where a.id=p_assignment;
 return query select s.id,s.student_id,p.full_name,s.text_answer,s.attempt_no,s.status,s.submitted_at,s.is_late,s.return_feedback,f.storage_path,f.original_name,f.mime_type,f.size_bytes,
 case when (grader and s.student_id<>auth.uid()) or public.is_owner() or g.released_at is not null then g.score end,case when (grader and s.student_id<>auth.uid()) or public.is_owner() or g.released_at is not null then g.feedback end,g.released_at
 from public.submissions s join public.profiles p on p.id=s.student_id left join public.files f on f.id=s.file_id left join public.grades g on g.submission_id=s.id
 where s.assignment_id=p_assignment and public.can_read_submission(s.id) order by s.attempt_no desc,s.submitted_at desc nulls first,s.id limit 50 offset p_offset;
end $$;
-- Teaching memberships do not consume the one registered learning group.
create or replace function public.redeem_invitation(p_token text) returns uuid
language plpgsql security definer set search_path=pg_catalog as $$
declare i public.invitations%rowtype;
begin
 if not public.is_active_user() then raise exception 'Access denied'; end if;
 select * into i from public.invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
 if not found then raise exception 'Invitation unavailable'; end if;
 if i.revoked or i.expires_at<=now() then raise exception 'Invitation unavailable'; end if;
 -- The inviter must retain the authority used to create this link.
 if not exists(select 1 from public.profiles where id=i.created_by and not blocked) then raise exception 'Invitation unavailable'; end if;
 if i.role='leader' then
  if not exists(select 1 from public.platform_owners where user_id=i.created_by) then raise exception 'Invitation unavailable'; end if;
 else
  if not exists(select 1 from public.study_groups where id=i.group_id and not blocked) then raise exception 'Group unavailable'; end if;
  if not exists(select 1 from public.platform_owners where user_id=i.created_by) and not exists(
   select 1 from public.group_memberships where user_id=i.created_by and group_id=i.group_id and role='leader' and active) then raise exception 'Invitation unavailable'; end if;
 end if;
 if exists(select 1 from public.invitation_redemptions where invitation_id=i.id and user_id=auth.uid()) then return i.group_id; end if;
 if i.used_count>=i.max_uses then raise exception 'Invitation unavailable'; end if;
 if i.role='leader' then
  insert into public.leader_entitlements(user_id) values(auth.uid())
  on conflict(user_id) do update set available_groups=public.leader_entitlements.available_groups+1;
 else
  if i.role='student' and exists(select 1 from public.group_memberships where user_id=auth.uid() and active and role in ('student','leader') and group_id<>i.group_id) then raise exception 'Group change requires owner'; end if;
  -- An invitation cannot reactivate a membership removed by an administrator.
  if exists(select 1 from public.group_memberships where group_id=i.group_id and user_id=auth.uid() and role=i.role and not active) then raise exception 'Membership disabled'; end if;
  insert into public.group_memberships(group_id,user_id,role) values(i.group_id,auth.uid(),i.role) on conflict do nothing;
  if i.role='teacher' then
   if exists(select 1 from public.invitation_courses ic join public.courses c on c.id=ic.course_id where ic.invitation_id=i.id and (c.group_id<>i.group_id or c.archived)) then raise exception 'Course unavailable'; end if;
   insert into public.teaching_assignments(course_id,group_id,teacher_id)
   select course_id,i.group_id,auth.uid() from public.invitation_courses where invitation_id=i.id on conflict do nothing;
  end if;
 end if;
 insert into public.invitation_redemptions values(i.id,auth.uid(),now());
 update public.invitations set used_count=used_count+1 where id=i.id;
 insert into public.audit_events(actor_id,action,entity_id) values(auth.uid(),'invitation.redeemed',i.id);
 return i.group_id;
end $$;

create or replace function public.request_group_access(p_group uuid) returns void
language plpgsql security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() or not exists(select 1 from public.study_groups where id=p_group and not blocked) then raise exception 'Group unavailable';end if;
 perform 1 from public.profiles where id=auth.uid() for update;
 if exists(select 1 from public.group_access_requests where user_id=auth.uid() and status='pending' and group_id<>p_group) then raise exception 'A request is already pending';end if;
 if exists(select 1 from public.group_memberships where user_id=auth.uid() and active and role in ('student','leader')) then raise exception 'Use owner to change existing membership';end if;
 if exists(select 1 from public.group_memberships where user_id=auth.uid() and group_id=p_group and role='student' and not active) then raise exception 'Membership disabled';end if;
 insert into public.group_access_requests(user_id,group_id) values(auth.uid(),p_group)
 on conflict(user_id) do update set group_id=excluded.group_id,status='pending',created_at=now()
 where public.group_access_requests.status<>'pending';
end $$;

create or replace function public.resolve_group_request(p_user uuid,p_group uuid,p_approve boolean) returns void
language plpgsql security definer set search_path=pg_catalog as $$
begin
 if not public.is_active_user() or not (public.is_owner() or public.is_group_leader(p_group)) or not exists(select 1 from public.study_groups where id=p_group and not blocked) then raise exception 'No rights';end if;
 -- Lock the account to serialize competing approvals, transfers and blocks.
 perform 1 from public.profiles where id=p_user and not blocked for update;
 if not found then raise exception 'Account unavailable';end if;
 perform 1 from public.group_access_requests where user_id=p_user and group_id=p_group and status='pending' for update;
 if not found then raise exception 'Request unavailable';end if;
 if p_approve then
  if exists(select 1 from public.group_memberships where user_id=p_user and active and role in ('student','leader')) then raise exception 'Account already has membership';end if;
  if exists(select 1 from public.group_memberships where user_id=p_user and group_id=p_group and role='student' and not active) then raise exception 'Membership disabled';end if;
  insert into public.group_memberships(user_id,group_id,role) values(p_user,p_group,'student');
 end if;
 update public.group_access_requests set status=case when p_approve then 'approved' else 'rejected' end where user_id=p_user;
 insert into public.audit_events(actor_id,action,entity_id,details) values(auth.uid(),'student.request_resolved',p_user,jsonb_build_object('group_id',p_group,'approved',p_approve));
end $$;

-- 202610160019_material_intake.sql; sha256=fa0da5e42b41d13ab9844a5e00480632123e34c0d569980bf68e348261898829
-- Gemini receives suggestions-only context; publication continues through existing RLS/RPC checks.
create or replace function public.can_publish_library_group(g uuid) returns boolean language sql stable security definer set search_path=pg_catalog as $$
 select public.is_active_user() and exists(select 1 from public.study_groups where id=g and not blocked) and (public.is_owner() or public.has_section_access('library') and (public.is_group_leader(g) or exists(select 1 from public.courses c where c.group_id=g and public.active_teaching_course(c.id))));
$$;
create or replace function public.manage_library_item(p_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog as $$
 select public.is_owner() or exists(select 1 from public.library_items i where i.id=p_id and i.author_id=auth.uid() and public.can_publish_library_group(i.source_group_id));
$$;
create or replace function public.material_intake_context() returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
declare result jsonb;
begin
 if not public.is_active_user() then raise exception 'Account unavailable';end if;
 select jsonb_build_object('courses',coalesce((select jsonb_agg(to_jsonb(q) order by q.group_name,q.title) from (
 select c.id,c.title,c.group_id,g.name as group_name,array_remove(array[
 case when public.manage_course_material(c.id,'lecture') then 'lecture' end,
 case when public.manage_course_material(c.id,'presentation') then 'presentation' end,
 case when public.manage_course_material(c.id,'material') then 'material' end,
 case when public.can_grade_course(c.id) and public.manage_course_material(c.id,'material') then 'assignment' end],null) as kinds
 from public.courses c join public.study_groups g on g.id=c.group_id where not c.archived and not g.blocked and (public.manage_course_material(c.id,'lecture') or public.manage_course_material(c.id,'presentation') or public.manage_course_material(c.id,'material'))
 )q),'[]'::jsonb),'groups',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name) order by g.name) from public.study_groups g where public.can_publish_library_group(g.id)),'[]'::jsonb)) into result;
 if jsonb_array_length(result->'courses')=0 and jsonb_array_length(result->'groups')=0 then raise exception 'Publisher required';end if;
 return result;
end $$;
create table if not exists public.material_ai_usage(user_id uuid not null references public.profiles(id),day date not null,requests integer not null check(requests>0),primary key(user_id,day));
alter table public.material_ai_usage enable row level security;
revoke all on public.material_ai_usage from public,anon,authenticated;
create or replace function public.begin_material_analysis() returns void language plpgsql security definer set search_path=pg_catalog as $$
declare today date:=(now() at time zone 'Asia/Bishkek')::date;used integer;
begin
 perform public.material_intake_context();perform pg_advisory_xact_lock(730049);
 select requests into used from public.material_ai_usage where user_id=auth.uid() and day=today;
 if coalesce(used,0)>=10 or (select coalesce(sum(requests),0) from public.material_ai_usage where day=today)>=100 then raise exception 'Analysis daily quota exceeded';end if;
 insert into public.material_ai_usage values(auth.uid(),today,1) on conflict(user_id,day) do update set requests=public.material_ai_usage.requests+1;
 delete from public.material_ai_usage where day<today-31;
end $$;
alter table public.assignments add column if not exists source_material_id uuid references public.course_content(id) on delete set null;
-- Assignment instructions belong to assignment access, including when general materials are denied.
create or replace function public.read_course_material(p_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog as $$
 select exists(select 1 from public.course_content i join public.courses c on c.id=i.course_id where i.id=p_id and public.can_view_course(c.id) and
 ((public.has_section_access(public.content_section(i.kind),c.group_id,c.id) and public.manage_course_material(c.id,i.kind)) or
 (i.published_at<=now() and (i.file_id is null or exists(select 1 from public.files f where f.id=i.file_id and f.status='ready')) and
 (public.has_section_access(public.content_section(i.kind),c.group_id,c.id) or exists(select 1 from public.assignments a where a.source_material_id=i.id and public.can_read_assignment(a.id))))));
$$;
-- The instruction attachment must not disappear through the ordinary material delete button.
create or replace function public.protect_assignment_source() returns trigger language plpgsql security definer set search_path=pg_catalog as $$
begin
 if exists(select 1 from public.assignments where source_material_id=old.id) then
  if TG_OP='DELETE' then raise exception 'Файл прикреплён к заданию. Его нельзя удалить как обычный материал.';end if;
  if new.file_id is distinct from old.file_id or new.published_at is null then raise exception 'Файл прикреплён к заданию. Его нельзя удалить как обычный материал.';end if;
 end if;
 if TG_OP='DELETE' then return old;end if;return new;
end $$;
revoke all on function public.protect_assignment_source() from public,anon,authenticated;
drop trigger if exists course_assignment_source_guard on public.course_content;
create trigger course_assignment_source_guard before update or delete on public.course_content for each row execute function public.protect_assignment_source();
create table if not exists public.material_intakes(request_id uuid primary key,user_id uuid not null references public.profiles(id),payload jsonb not null,item_id uuid not null,bucket text not null,path text not null,result_id uuid,created_at timestamptz not null default now());
alter table public.material_intakes enable row level security;
revoke all on public.material_intakes from public,anon,authenticated;
create or replace function public.prepare_material_intake(p_request uuid,p_kind text,p_course uuid,p_group uuid,p_title text,p_description text,p_due timestamptz,p_max integer,p_late boolean,p_name text,p_mime text,p_size bigint,p_hash text) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare payload jsonb;old public.material_intakes%rowtype;iid uuid;path text;bucket text;fid uuid;lim public.storage_limits%rowtype;
begin
 perform public.material_intake_context();perform pg_advisory_xact_lock(730041);
 if p_request is null or p_kind is null or p_kind not in ('lecture','presentation','material','assignment','book') or p_title is null or length(trim(p_title)) not between 1 and 200 or p_description is null or length(p_description)>50000 or p_hash is null or p_hash!~'^[a-f0-9]{64}$' then raise exception 'Invalid intake';end if;
 if p_kind='book' then if not public.can_publish_library_group(p_group) then raise exception 'Access denied';end if;
 else if p_course is null or not public.manage_course_material(p_course,(case when p_kind='assignment' then 'material' else p_kind end)::public.content_kind) then raise exception 'Access denied';end if;
 if p_kind='assignment' and (not public.can_grade_course(p_course) or length(trim(p_description))=0 or p_max is null or p_max not between 1 and 1000 or p_late is null) then raise exception 'Assignment unavailable';end if;end if;
 payload:=jsonb_build_object('kind',p_kind,'course',p_course,'group',p_group,'title',trim(p_title),'description',p_description,'due',p_due,'max',p_max,'late',p_late,'name',p_name,'mime',p_mime,'size',p_size,'hash',p_hash);
 select * into old from public.material_intakes where request_id=p_request;
 if found then
  if old.user_id<>auth.uid() or old.payload<>payload then raise exception 'Intake changed';end if;
  return jsonb_build_object('item_id',old.item_id,'path',old.path,'bucket',old.bucket,'published',old.result_id is not null,'result_id',old.result_id);
 end if;
 if p_kind='book' then
  -- Mirror library reservation invariants while allowing active teachers to publish their own books.
  select * into lim from public.storage_limits where singleton;
  if p_size is null or p_size<=0 or p_size>lim.file_limit_bytes or p_name is null or length(p_name) not between 1 and 240 or not coalesce((select p_mime=any(allowed_mime_types) from storage.buckets where id='studyhub-library'),false) then raise exception 'Invalid file';end if;
  if exists(select 1 from public.files where owner_id=auth.uid() and status='reserved') then raise exception 'Finish or delete previous upload';end if;
  if public.library_usage_bytes()+lim.file_limit_bytes>lim.budget_bytes then raise exception 'Storage budget exceeded';end if;
  fid:=gen_random_uuid();path:=auth.uid()::text||'/'||fid::text||'/content';
  insert into public.files(id,owner_id,storage_path,original_name,mime_type,size_bytes) values(fid,auth.uid(),path,p_name,p_mime,p_size);
  insert into public.library_items(title,author_id,source_group_id,file_id) values(trim(p_title),auth.uid(),p_group,fid) returning id into iid;bucket:='studyhub-library';
 else
  select r.item_id,r.storage_path into iid,path from public.reserve_course_upload(p_course,(case when p_kind='assignment' then 'material' else p_kind end)::public.content_kind,p_title,p_description,p_name,p_mime,p_size)r;bucket:='studyhub-courses';
 end if;
 insert into public.material_intakes(request_id,user_id,payload,item_id,bucket,path) values(p_request,auth.uid(),payload,iid,bucket,path);
 return jsonb_build_object('item_id',iid,'path',path,'bucket',bucket,'published',false,'result_id',null);
end $$;
create or replace function public.finish_material_intake(p_request uuid) returns uuid language plpgsql security definer set search_path=pg_catalog as $$
declare job public.material_intakes%rowtype;result uuid;c uuid;
begin
 perform pg_advisory_xact_lock(730041);select * into job from public.material_intakes where request_id=p_request for update;
 if not found or job.user_id<>auth.uid() then raise exception 'Intake unavailable';end if;
 perform public.material_intake_context();
 if job.bucket='studyhub-library' then
  if not public.can_publish_library_group((job.payload->>'group')::uuid) then raise exception 'Access denied';end if;
 else
  c:=(job.payload->>'course')::uuid;
  if not public.manage_course_material(c,(case when job.payload->>'kind'='assignment' then 'material' else job.payload->>'kind' end)::public.content_kind) or (job.payload->>'kind'='assignment' and not public.can_grade_course(c)) then raise exception 'Access denied';end if;
 end if;
 if job.result_id is not null then return job.result_id;end if;
 if job.bucket='studyhub-library' then perform public.publish_library_upload(job.item_id);result:=job.item_id;
 else
  perform public.publish_course_upload(job.item_id);result:=job.item_id;
  if job.payload->>'kind'='assignment' then
   result:=public.create_assignment(c,job.payload->>'title',job.payload->>'description',(job.payload->>'due')::timestamptz,(job.payload->>'max')::integer,(job.payload->>'late')::boolean);
   update public.assignments set source_material_id=job.item_id where id=result;
  end if;
 end if;
 update public.material_intakes set result_id=result where request_id=p_request;
 insert into public.audit_events(actor_id,action,entity_id,details) values(auth.uid(),'material.intake_published',result,jsonb_build_object('kind',job.payload->>'kind','source',job.item_id));
 return result;
end $$;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('can_publish_library_group','material_intake_context','begin_material_analysis','prepare_material_intake','finish_material_intake') loop execute 'revoke all on function '||f.signature||' from public,anon';execute 'grant execute on function '||f.signature||' to authenticated';end loop;end $$;

-- 202610160020_ai_economy.sql; sha256=f3173ad72edef3c0b11ea97cea4e428ab06220f912c9f0b9d459edd3edc2f793
create table if not exists public.material_ai_limits(singleton boolean primary key default true check(singleton),user_daily integer not null default 5 check(user_daily between 1 and 1000),project_daily integer not null default 20 check(project_daily between 1 and 10000),rpm integer not null default 2 check(rpm between 1 and 1000),tpm integer not null default 12000 check(tpm between 1000 and 1000000),max_input integer not null default 8000 check(max_input>0),max_output integer not null default 2048 check(max_output>0),blocked_until timestamptz,check(max_input+max_output<=tpm));
insert into public.material_ai_limits(singleton) values(true) on conflict do nothing;
create table if not exists public.material_ai_runs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),cache_key text not null,started_at timestamptz not null default clock_timestamp(),tokens integer not null check(tokens>=0),status text not null default 'running' check(status in ('running','ready','failed')));
create index if not exists material_ai_runs_recent on public.material_ai_runs(started_at);
create table if not exists public.material_ai_cache(user_id uuid not null references public.profiles(id),cache_key text not null check(cache_key~'^[a-f0-9]{64}$'),result jsonb not null,expires_at timestamptz not null default now()+interval '7 days',primary key(user_id,cache_key));
alter table public.material_ai_limits enable row level security;
alter table public.material_ai_runs enable row level security;
alter table public.material_ai_cache enable row level security;
revoke all on public.material_ai_limits,public.material_ai_runs,public.material_ai_cache from public,anon,authenticated;
create or replace function public.material_ai_quota_for(p_user uuid) returns jsonb language sql stable security definer set search_path=pg_catalog as $$
 select jsonb_build_object('user_daily',l.user_daily,'project_daily',l.project_daily,'rpm',l.rpm,'tpm',l.tpm,'max_input',l.max_input,'max_output',l.max_output,
 'user_remaining',greatest(0,l.user_daily-coalesce((select requests from public.material_ai_usage where user_id=p_user and day=(now() at time zone 'Asia/Bishkek')::date),0)),
 'project_remaining',greatest(0,l.project_daily-(select coalesce(sum(requests),0) from public.material_ai_usage where day=(now() at time zone 'Asia/Bishkek')::date)),
 'minute_remaining',greatest(0,l.rpm-(select count(*) from public.material_ai_runs where started_at>now()-interval '60 seconds')),
 'tokens_remaining',greatest(0,l.tpm-(select coalesce(sum(tokens),0) from public.material_ai_runs where started_at>now()-interval '60 seconds')),
 'retry_after_seconds',greatest(0,ceil(extract(epoch from coalesce(l.blocked_until,now())-now())))::integer,
 'resets_at',(((now() at time zone 'Asia/Bishkek')::date+1)::timestamp at time zone 'Asia/Bishkek')) from public.material_ai_limits l where singleton;
$$;
create or replace function public.material_ai_quota() returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$begin perform public.material_intake_context();return public.material_ai_quota_for(auth.uid());end $$;
-- Claims and completions are server-only. Browser clients cannot forge usage or poison cache.
create or replace function public.claim_material_analysis(p_user uuid,p_key text) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare q jsonb;l public.material_ai_limits%rowtype;cached jsonb;run uuid;today date:=(now() at time zone 'Asia/Bishkek')::date;
begin
 if p_key is null or p_key!~'^[a-f0-9]{64}$' or not exists(select 1 from public.profiles where id=p_user and not blocked) then raise exception 'Account unavailable';end if;
 perform pg_advisory_xact_lock(730049);
 select result into cached from public.material_ai_cache where user_id=p_user and cache_key=p_key and expires_at>now();
 if found then return jsonb_build_object('status','cached','analysis',cached,'quota',public.material_ai_quota_for(p_user));end if;
 q:=public.material_ai_quota_for(p_user);select * into l from public.material_ai_limits where singleton;
 if exists(select 1 from public.material_ai_runs where user_id=p_user and cache_key=p_key and status='running' and started_at>now()-interval '90 seconds') then return jsonb_build_object('status','busy','quota',q);end if;
 if (q->>'user_remaining')::int=0 or (q->>'project_remaining')::int=0 or (q->>'minute_remaining')::int=0 or (q->>'tokens_remaining')::int<l.max_output+1 or (q->>'retry_after_seconds')::int>0 then return jsonb_build_object('status','limited','quota',q);end if;
 insert into public.material_ai_usage values(p_user,today,1) on conflict(user_id,day) do update set requests=public.material_ai_usage.requests+1;
 insert into public.material_ai_runs(user_id,cache_key,tokens) values(p_user,p_key,l.max_output) returning id into run;
 delete from public.material_ai_runs where started_at<now()-interval '32 days';delete from public.material_ai_cache where expires_at<now();
 return jsonb_build_object('status','claimed','reservation',run,'quota',public.material_ai_quota_for(p_user));
end $$;
create or replace function public.meter_material_analysis(p_id uuid,p_input integer) returns boolean language plpgsql security definer set search_path=pg_catalog as $$
declare l public.material_ai_limits%rowtype;r public.material_ai_runs%rowtype;
begin
 perform pg_advisory_xact_lock(730049);select * into l from public.material_ai_limits where singleton;select * into r from public.material_ai_runs where id=p_id for update;
 if not found or r.status<>'running' or r.started_at<now()-interval '90 seconds' then return false;end if;
 if p_input is null or p_input<1 or p_input>l.max_input or (select coalesce(sum(tokens),0) from public.material_ai_runs where id<>p_id and started_at>now()-interval '60 seconds')+p_input+l.max_output>l.tpm then update public.material_ai_runs set status='failed' where id=p_id;return false;end if;
 update public.material_ai_runs set tokens=p_input+l.max_output,started_at=clock_timestamp() where id=p_id;return true;
end $$;
create or replace function public.finish_material_analysis(p_id uuid,p_result jsonb default null,p_pause integer default 0) returns void language plpgsql security definer set search_path=pg_catalog as $$
declare r public.material_ai_runs%rowtype;
begin
 perform pg_advisory_xact_lock(730049);select * into r from public.material_ai_runs where id=p_id for update;if not found or r.status<>'running' then return;end if;
 if p_result is not null and r.started_at>now()-interval '90 seconds' then
  insert into public.material_ai_cache(user_id,cache_key,result) values(r.user_id,r.cache_key,p_result) on conflict(user_id,cache_key) do update set result=excluded.result,expires_at=now()+interval '7 days';
  -- Bound the amount of retained classification text per user.
  delete from public.material_ai_cache where user_id=r.user_id and cache_key in(select cache_key from public.material_ai_cache where user_id=r.user_id order by expires_at desc,cache_key offset 100);
  update public.material_ai_runs set status='ready' where id=p_id;
 else update public.material_ai_runs set status='failed' where id=p_id;end if;
 if p_pause>0 then update public.material_ai_limits set blocked_until=greatest(coalesce(blocked_until,now()),now()+make_interval(secs=>least(p_pause,3600))) where singleton;end if;
end $$;
revoke all on function public.material_ai_quota_for(uuid) from public,anon,authenticated;
grant execute on function public.material_ai_quota_for(uuid) to service_role;
revoke all on function public.material_ai_quota() from public,anon;
grant execute on function public.material_ai_quota() to authenticated;
revoke all on function public.claim_material_analysis(uuid,text),public.meter_material_analysis(uuid,integer),public.finish_material_analysis(uuid,jsonb,integer) from public,anon,authenticated;
grant execute on function public.claim_material_analysis(uuid,text),public.meter_material_analysis(uuid,integer),public.finish_material_analysis(uuid,jsonb,integer) to service_role;
revoke all on function public.begin_material_analysis() from public,anon,authenticated;

-- 202610160021_upload_recovery.sql; sha256=b93563b334b8b5c99447927ae66153b0435a42539a39caa1cf7f5e0f2de3aabd
alter table public.material_intakes add column if not exists cancelled_at timestamptz;
alter table public.material_intakes add column if not exists cleaned_at timestamptz;
-- Serialize cancellation with prepare/finish and existing storage deletion operations.
create or replace function public.material_intake_status(p_request uuid) returns jsonb
language plpgsql security definer set search_path=pg_catalog as $$
declare job public.material_intakes%rowtype;
begin
 if not public.is_active_user() then raise exception 'Account unavailable';end if;
 select * into job from public.material_intakes where request_id=p_request;
 if not found then return jsonb_build_object('status','none');end if;
 if job.user_id<>auth.uid() then raise exception 'Intake unavailable';end if;
 return jsonb_build_object('status',case when job.cleaned_at is not null then 'cancelled' when job.cancelled_at is not null then 'deleting' when job.result_id is not null then 'published' else 'pending' end,'result_id',job.result_id);
end $$;
create or replace function public.begin_material_intake_cancel(p_request uuid) returns jsonb
language plpgsql security definer set search_path=pg_catalog as $$
declare job public.material_intakes%rowtype;
begin
 if not public.is_active_user() or p_request is null then raise exception 'Account unavailable';end if;
 perform pg_advisory_xact_lock(730041);
 select * into job from public.material_intakes where request_id=p_request for update;
 if not found then
  perform public.material_intake_context();
  -- A tombstone also prevents a delayed prepare from starting after cancellation.
  insert into public.material_intakes(request_id,user_id,payload,item_id,bucket,path,cancelled_at,cleaned_at)
   values(p_request,auth.uid(),'{}',gen_random_uuid(),'','',now(),now());
  return jsonb_build_object('status','cancelled');
 end if;
 if job.user_id<>auth.uid() then raise exception 'Intake unavailable';end if;
 if job.result_id is not null then return jsonb_build_object('status','published','result_id',job.result_id);end if;
 if job.cleaned_at is not null then return jsonb_build_object('status','cancelled');end if;
 if job.bucket='studyhub-library' and exists(select 1 from public.library_items where id=job.item_id) then perform public.begin_library_delete(job.item_id);
 elsif job.bucket='studyhub-courses' and exists(select 1 from public.course_content where id=job.item_id) then perform public.begin_course_delete(job.item_id);
 end if;
 update public.material_intakes set cancelled_at=coalesce(cancelled_at,now()) where request_id=p_request;
 return jsonb_build_object('status','deleting','bucket',job.bucket,'path',job.path);
end $$;
create or replace function public.finish_material_intake_cancel(p_request uuid) returns void
language plpgsql security definer set search_path=pg_catalog as $$
declare job public.material_intakes%rowtype;
begin
 if not public.is_active_user() then raise exception 'Account unavailable';end if;
 perform pg_advisory_xact_lock(730041);
 select * into job from public.material_intakes where request_id=p_request for update;
 if not found or job.user_id<>auth.uid() or job.cancelled_at is null or job.result_id is not null then raise exception 'Cancellation unavailable';end if;
 if job.cleaned_at is not null then return;end if;
 if exists(select 1 from storage.objects where bucket_id=job.bucket and name=job.path) then raise exception 'Remove object through Storage API first';end if;
 if job.bucket='studyhub-library' and exists(select 1 from public.library_items where id=job.item_id) then perform public.finish_library_delete(job.item_id);
 elsif job.bucket='studyhub-courses' and exists(select 1 from public.course_content where id=job.item_id) then perform public.finish_course_delete(job.item_id);
 end if;
 update public.material_intakes set cleaned_at=now() where request_id=p_request;
 insert into public.audit_events(actor_id,action,entity_id) values(auth.uid(),'material.intake_cancelled',job.item_id);
end $$;
create or replace function public.finish_material_intake(p_request uuid) returns uuid language plpgsql security definer set search_path=pg_catalog as $$
declare job public.material_intakes%rowtype;result uuid;c uuid;
begin
 perform pg_advisory_xact_lock(730041);select * into job from public.material_intakes where request_id=p_request for update;
 if not found or job.user_id<>auth.uid() then raise exception 'Intake unavailable';end if;
 if job.cancelled_at is not null then raise exception 'Intake cancelled';end if;
 perform public.material_intake_context();
 if job.bucket='studyhub-library' then
  if not public.can_publish_library_group((job.payload->>'group')::uuid) then raise exception 'Access denied';end if;
 else
  c:=(job.payload->>'course')::uuid;
  if not public.manage_course_material(c,(case when job.payload->>'kind'='assignment' then 'material' else job.payload->>'kind' end)::public.content_kind) or (job.payload->>'kind'='assignment' and not public.can_grade_course(c)) then raise exception 'Access denied';end if;
 end if;
 if job.result_id is not null then return job.result_id;end if;
 if job.bucket='studyhub-library' then perform public.publish_library_upload(job.item_id);result:=job.item_id;
 else
  perform public.publish_course_upload(job.item_id);result:=job.item_id;
  if job.payload->>'kind'='assignment' then
   result:=public.create_assignment(c,job.payload->>'title',job.payload->>'description',(job.payload->>'due')::timestamptz,(job.payload->>'max')::integer,(job.payload->>'late')::boolean);
   update public.assignments set source_material_id=job.item_id where id=result;
  end if;
 end if;
 update public.material_intakes set result_id=result where request_id=p_request;
 insert into public.audit_events(actor_id,action,entity_id,details) values(auth.uid(),'material.intake_published',result,jsonb_build_object('kind',job.payload->>'kind','source',job.item_id));
 return result;
end $$;

revoke all on function public.material_intake_status(uuid),public.begin_material_intake_cancel(uuid),public.finish_material_intake_cancel(uuid) from public,anon;
grant execute on function public.material_intake_status(uuid),public.begin_material_intake_cancel(uuid),public.finish_material_intake_cancel(uuid) to authenticated;
notify pgrst, 'reload schema';

-- 202610170022_course_management.sql; sha256=0318cf5fb42ae7e4fa631146aa7aea2870a411c8c32a204b08507f49baf09385
do $$ begin
 if to_regclass('public.courses') is null or to_regclass('public.material_intakes') is null or to_regclass('public.private_tasks') is null then
  raise exception 'Existing StudyHub database v0.35 required. Check selected project; no changes applied.';
 end if;
end $$;
-- Managers can list archived metadata for restoration, without opening its materials.
drop policy if exists courses_read on public.courses;
create policy courses_read on public.courses for select to authenticated using (
 public.can_view_course(id) or (archived and public.is_group_leader(group_id))
);
create or replace function public.manage_course(p_course uuid,p_action text,p_title text,p_expected_title text,p_expected_archived boolean) returns void
language plpgsql security definer set search_path=pg_catalog as $$
declare c public.courses%rowtype; next_title text;
begin
 if not public.is_active_user() then raise exception 'Course management denied';end if;
 select * into c from public.courses where id=p_course for update;
 if not found or not(public.is_owner() or public.is_group_leader(c.group_id)) then raise exception 'Course management denied';end if;
 if p_action not in ('rename','archive','restore','delete') or p_action is null then raise exception 'Invalid course action';end if;
 next_title=trim(p_title);
 if p_action='rename' and (next_title is null or length(next_title) not between 1 and 200) then raise exception 'Invalid course title';end if;
 -- A retry of the same successful change is harmless.
 if p_action='rename' and c.title=next_title or p_action='archive' and c.archived or p_action='restore' and not c.archived then return;end if;
 if c.title is distinct from p_expected_title or c.archived is distinct from p_expected_archived then raise exception 'Course changed; refresh';end if;
 if p_action='delete' then
  if exists(select 1 from public.course_content where course_id=c.id)
   or exists(select 1 from public.assignments where course_id=c.id)
   or exists(select 1 from public.group_board where course_id=c.id)
   or exists(select 1 from public.course_topics where course_id=c.id)
   or exists(select 1 from public.course_topic_links where course_id=c.id)
   or exists(select 1 from public.teaching_assignments where course_id=c.id)
   or exists(select 1 from public.invitation_courses where course_id=c.id)
   or exists(select 1 from public.access_denials where course_id=c.id)
   or exists(select 1 from public.material_intakes where payload->>'course'=c.id::text)
   or exists(select 1 from public.private_notes where body like '%'||c.id::text||'%')
   or exists(select 1 from public.private_tasks where body like '%'||c.id::text||'%')
  then raise exception 'Course is not empty; archive instead';end if;
  delete from public.courses where id=c.id;
 else
  update public.courses set title=case when p_action='rename' then next_title else title end,
   archived=case when p_action='archive' then true when p_action='restore' then false else archived end where id=c.id;
 end if;
 insert into public.audit_events(actor_id,action,entity_id,details) values(auth.uid(),case p_action when 'rename' then 'course.renamed' when 'archive' then 'course.archived' when 'restore' then 'course.restored' else 'course.deleted' end,c.id,jsonb_build_object('group_id',c.group_id,'title',c.title,'new_title',case when p_action='rename' then next_title else c.title end));
end $$;
revoke all on function public.manage_course(uuid,text,text,text,boolean) from public,anon;
grant execute on function public.manage_course(uuid,text,text,text,boolean) to authenticated;

-- 202610170023_study_search.sql; sha256=ddd9cad79bec784bb43c0885c9914f7d1dd6b830aaf647652679a5757430c946
do $$ begin
 if to_regclass('public.private_tasks') is null or to_regclass('public.material_intakes') is null then
  raise exception 'Existing StudyHub database v0.35 required. Check selected project; no changes applied.';
 end if;
end $$;
-- Only visible note text is indexed, not the JSON metadata used to link notes.
create or replace function public.study_search_text(body text) returns text
language plpgsql immutable set search_path=pg_catalog as $$
declare value jsonb;
begin
 begin value:=body::jsonb;exception when others then return coalesce(body,'');end;
 if jsonb_typeof(value)='object' then
  if value->>'studyhub_reader_note'='1' then return coalesce(value->>'text','')||' '||coalesce(value->>'quote','');end if;
  if value->>'studyhub_course_note'='1' then return coalesce(value->>'text','');end if;
  if value->>'studyhub_plan'='1' then return coalesce(value->>'details','');end if;
 end if;
 return coalesce(body,'');
end $$;
create or replace function public.study_search_vector(title text,body text) returns tsvector
language sql immutable set search_path=pg_catalog as $$
 select setweight(to_tsvector('pg_catalog.russian',coalesce(title,'')),'A')||setweight(to_tsvector('pg_catalog.russian',coalesce(body,'')),'B');
$$;
create index if not exists courses_search_gin on public.courses using gin(public.study_search_vector(title,''));
create index if not exists content_search_gin on public.course_content using gin(public.study_search_vector(title,body));
create index if not exists assignments_search_gin on public.assignments using gin(public.study_search_vector(title,description));
create index if not exists library_search_gin on public.library_items using gin(public.study_search_vector(title,''));
create index if not exists filenames_search_gin on public.files using gin(public.study_search_vector(original_name,''));
create index if not exists notes_search_gin on public.private_notes using gin(public.study_search_vector(title,public.study_search_text(body)));
create index if not exists tasks_search_gin on public.private_tasks using gin(public.study_search_vector(title,public.study_search_text(body)));
create or replace function public.study_search(p_query text,p_kind text default 'all',p_offset integer default 0) returns jsonb
language plpgsql stable security definer set search_path=pg_catalog as $$
declare raw text; query tsquery; lexemes text; result jsonb;
begin
 if not public.is_active_user() then raise exception 'Search access denied';end if;
 raw:=lower(trim(p_query));
 if raw is null or length(raw)<2 or length(raw)>200 or p_kind is null or p_kind not in ('all','course','material','assignment','book','note') or p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'Invalid search';end if;
 -- Lexemes come from the text parser, not from user-supplied tsquery syntax.
 select string_agg(quote_literal(word)||':*',' & ') into lexemes from unnest(tsvector_to_array(to_tsvector('pg_catalog.russian',raw))) word;
 if lexemes is null then return jsonb_build_object('items','[]'::jsonb,'hasMore',false,'issues','[]'::jsonb);end if;
 query:=to_tsquery('pg_catalog.russian',lexemes);
 with docs as (
  select 'course'::text kind,c.id,c.title,''::text body,c.id course_id,c.title course_title,false has_file,null::timestamptz due,null::text status,public.study_search_vector(c.title,'') vec
  from public.courses c where p_kind in ('all','course') and not c.archived and public.can_view_course(c.id) and public.study_search_vector(c.title,'')@@query
  union all
  select 'material',i.id,i.title,coalesce(i.body,'')||' '||coalesce(f.original_name,''),c.id,c.title,i.file_id is not null,null,null,public.study_search_vector(i.title,i.body)||public.study_search_vector(f.original_name,'')
  from public.course_content i join public.courses c on c.id=i.course_id left join public.files f on f.id=i.file_id
  where p_kind in ('all','material') and not c.archived and i.kind in ('lecture','presentation','material') and i.published_at<=now() and (i.file_id is null or f.status='ready') and public.read_course_material(i.id)
   and (public.study_search_vector(i.title,i.body)@@query or public.study_search_vector(f.original_name,'')@@query)
  union all
  select 'assignment',a.id,a.title,a.description,c.id,c.title,false,a.due_at,
   case when public.can_submit_assignment(a.id) then coalesce((select w.status from public.submissions w where w.assignment_id=a.id and w.student_id=auth.uid() order by w.attempt_no desc limit 1),'not_submitted') end,
   public.study_search_vector(a.title,a.description)
  from public.assignments a join public.courses c on c.id=a.course_id where p_kind in ('all','assignment') and not c.archived and public.can_read_assignment(a.id) and public.study_search_vector(a.title,a.description)@@query
  union all
  select 'book',i.id,i.title,f.original_name,null,null,true,null,null,public.study_search_vector(i.title,'')||public.study_search_vector(f.original_name,'')
  from public.library_items i join public.files f on f.id=i.file_id where p_kind in ('all','book') and i.status='published' and f.status='ready' and public.has_section_access('library') and public.read_library_file(f.storage_path)
   and (public.study_search_vector(i.title,'')@@query or public.study_search_vector(f.original_name,'')@@query)
  union all
  select 'note',n.id,n.title,public.study_search_text(n.body),null,null,false,null,null,public.study_search_vector(n.title,public.study_search_text(n.body))
  from public.private_notes n where p_kind in ('all','note') and n.user_id=auth.uid() and not public.is_plan_record(n.body) and public.study_search_vector(n.title,public.study_search_text(n.body))@@query
  union all
  select 'plan',n.id,n.title,public.study_search_text(n.body),null,null,false,
   case when public.is_plan_record(n.body) then ((n.body::jsonb->>'due')||'T23:59:59+06:00')::timestamptz end,
   case when public.is_plan_record(n.body) and n.body::jsonb->>'done'='true' then 'completed' else 'pending' end,
   public.study_search_vector(n.title,public.study_search_text(n.body))
  from public.private_tasks n where p_kind in ('all','assignment') and n.user_id=auth.uid() and public.is_plan_record(n.body) and public.study_search_vector(n.title,public.study_search_text(n.body))@@query
 ), ranked as (
  select *,case when lower(title)=raw then 100 when starts_with(lower(title),raw) then 70 when public.study_search_vector(title,'')@@query then 50 else 0 end+ts_rank_cd(vec,query) score from docs
 ), page as (select * from ranked order by score desc,title,kind,id limit 26 offset p_offset), numbered as (select *,row_number() over(order by score desc,title,kind,id) n from page)
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'id',id,'title',title,
  'highlightedTitle',ts_headline('pg_catalog.russian',title,query,'StartSel=⟦,StopSel=⟧,HighlightAll=true'),
  'snippet',left(ts_headline('pg_catalog.russian',case when body='' then title else body end,query,'StartSel=⟦,StopSel=⟧,MaxWords=32,MinWords=12,MaxFragments=1'),500),
  'courseId',course_id,'courseTitle',course_title,'hasFile',has_file,'due',due,'status',status) order by score desc,title,kind,id) from numbered where n<=25),'[]'::jsonb),
  'hasMore',exists(select 1 from numbered where n=26),'issues','[]'::jsonb) into result;
 return result;
end $$;
create or replace function public.study_search_note(p_id uuid) returns setof public.private_notes
language sql stable security definer set search_path=pg_catalog as $$
 select * from public.private_notes n where n.id=p_id and n.user_id=auth.uid() and public.is_active_user() and not public.is_plan_record(n.body);
$$;
revoke all on function public.study_search(text,text,integer),public.study_search_note(uuid) from public,anon;
grant execute on function public.study_search(text,text,integer),public.study_search_note(uuid) to authenticated;

-- 202610170024_weekly_schedule.sql; sha256=5cea746f0b7e4c005b40f40cc3390f179f02a1c9ff6b13763f022f98a2f0ec5e
do $$ begin if to_regclass('public.material_intakes') is null then raise exception 'Existing StudyHub v0.35 database required';end if;end $$;
create table if not exists public.weekly_schedule_days(group_id uuid references public.study_groups(id),weekday integer check(weekday between 1 and 7),version integer not null default 0,request_id uuid,payload jsonb,primary key(group_id,weekday));
create table if not exists public.weekly_schedule_slots(id uuid primary key,group_id uuid not null references public.study_groups(id),weekday integer not null check(weekday between 1 and 7),course_id uuid not null references public.courses(id),start_time time not null,end_time time not null,location text not null default '' check(length(location)<=200),starts_on date not null,author_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),check(end_time>start_time));
create index if not exists weekly_slots_by_group on public.weekly_schedule_slots(group_id,weekday);
create table if not exists public.schedule_exceptions(slot_id uuid references public.weekly_schedule_slots(id) on delete cascade,day date not null,cancelled boolean not null,course_id uuid not null references public.courses(id),start_time time not null,end_time time not null,location text not null default '' check(length(location)<=200),version integer not null default 1,primary key(slot_id,day),check(end_time>start_time));
alter table public.weekly_schedule_days enable row level security;alter table public.weekly_schedule_slots enable row level security;alter table public.schedule_exceptions enable row level security;
revoke all on public.weekly_schedule_days,public.weekly_schedule_slots,public.schedule_exceptions from anon,authenticated;
create or replace function public.weekly_schedule_day(p_group uuid,p_day integer) returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$
begin
 if not public.write_group_board(p_group,null,'schedule') then raise exception 'Schedule management denied';end if;
 if exists(select 1 from public.weekly_schedule_slots where group_id=p_group and weekday=p_day and not public.write_group_board(p_group,course_id,'schedule')) then raise exception 'Schedule management denied';end if;
 return jsonb_build_object('version',coalesce((select version from public.weekly_schedule_days where group_id=p_group and weekday=p_day),0),'items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'course_id',course_id,'start_time',to_char(start_time,'HH24:MI'),'end_time',to_char(end_time,'HH24:MI'),'location',location) order by start_time,id) from public.weekly_schedule_slots where group_id=p_group and weekday=p_day),'[]'::jsonb));
end $$;
create or replace function public.save_weekly_schedule(p_group uuid,p_day integer,p_items jsonb,p_version integer,p_request uuid) returns void language plpgsql security definer set search_path=pg_catalog as $$
declare state public.weekly_schedule_days; r jsonb; slot_id uuid; course uuid; start_at time; end_at time; seen uuid[]:='{}';last_end time;check_day date;
begin
 if not public.write_group_board(p_group,null,'schedule') then raise exception 'Schedule management denied';end if;
 if p_day is null or p_day not between 1 and 7 or p_request is null or p_version is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>24 then raise exception 'Invalid weekly schedule';end if;
 insert into public.weekly_schedule_days(group_id,weekday) values(p_group,p_day) on conflict do nothing;
 select * into state from public.weekly_schedule_days where group_id=p_group and weekday=p_day for update;
 if state.request_id=p_request then if state.payload=p_items then return;else raise exception 'Request changed';end if;end if;
 if exists(select 1 from public.weekly_schedule_slots where group_id=p_group and weekday=p_day and not public.write_group_board(p_group,course_id,'schedule')) then raise exception 'Schedule management denied';end if;
 if state.version<>p_version then raise exception 'Schedule changed. Refresh before saving';end if;
 for r in select value from jsonb_array_elements(p_items) order by value->>'start_time' loop
  slot_id:=(r->>'id')::uuid;course:=(r->>'course_id')::uuid;
  if slot_id is null or course is null or slot_id=any(seen) or coalesce(r->>'start_time','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' or coalesce(r->>'end_time','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' or length(coalesce(r->>'location',''))>200 then raise exception 'Invalid lesson';end if;
  if not public.write_group_board(p_group,course,'schedule') or not exists(select 1 from public.courses where id=course and group_id=p_group and not archived) then raise exception 'Course unavailable in group';end if;
  if exists(select 1 from public.weekly_schedule_slots where id=slot_id and (group_id<>p_group or weekday<>p_day)) then raise exception 'Foreign lesson';end if;
  start_at:=(r->>'start_time')::time;end_at:=(r->>'end_time')::time;
  if end_at<=start_at or (last_end is not null and start_at<last_end) then raise exception 'Lessons overlap or invalid time';end if;
  last_end:=end_at;seen:=array_append(seen,slot_id);
  insert into public.weekly_schedule_slots(id,group_id,weekday,course_id,start_time,end_time,location,starts_on,author_id) values(slot_id,p_group,p_day,course,start_at,end_at,coalesce(r->>'location',''),date_trunc('week',now() at time zone 'Asia/Bishkek')::date,auth.uid()) on conflict(id) do update set course_id=excluded.course_id,start_time=excluded.start_time,end_time=excluded.end_time,location=excluded.location where weekly_schedule_slots.group_id=p_group and weekly_schedule_slots.weekday=p_day;
  if not found then raise exception 'Foreign lesson';end if;
 end loop;
 delete from public.weekly_schedule_slots where group_id=p_group and weekday=p_day and not(id=any(seen));
 -- A changed weekly pattern must remain compatible with dated exceptions.
 for check_day in select distinct e.day from public.schedule_exceptions e join public.weekly_schedule_slots t on t.id=e.slot_id where t.group_id=p_group and extract(isodow from e.day)=p_day and e.day>=(now() at time zone 'Asia/Bishkek')::date loop
  if exists(with entries as(select * from public.schedule_rows(p_group,check_day::timestamp at time zone 'Asia/Bishkek',(check_day+1)::timestamp at time zone 'Asia/Bishkek')) select 1 from entries a join entries b on a.id<b.id and a.starts_at<b.ends_at and a.ends_at>b.starts_at where not a.cancelled and not b.cancelled and a.template_id is not null and b.template_id is not null) then raise exception 'Lessons overlap or invalid time';end if;
 end loop;
 update public.weekly_schedule_days set version=version+1,request_id=p_request,payload=p_items where group_id=p_group and weekday=p_day;
 insert into public.audit_events(actor_id,action,entity_id,details) values(auth.uid(),'schedule.weekly.saved',p_group,jsonb_build_object('weekday',p_day,'lessons',jsonb_array_length(p_items)));
end $$;
-- A common expansion feeds the day, home screen, calendar and subject pages.
create or replace function public.schedule_rows(p_group uuid,p_from timestamptz,p_to timestamptz)
returns table(id uuid,group_id uuid,course_id uuid,kind text,title text,body text,location text,starts_at timestamptz,ends_at timestamptz,author_name text,created_at timestamptz,can_manage boolean,template_id uuid,occurrence_date date,cancelled boolean,version integer)
language sql stable security definer set search_path=pg_catalog as $$
 with dates as(select d::date as occurrence_day from generate_series((p_from at time zone 'Asia/Bishkek')::date::timestamp-interval '1 day',(p_to at time zone 'Asia/Bishkek')::date::timestamp,interval '1 day')d),occurrences as (
 select s.*,d.occurrence_day,e.cancelled,coalesce(e.course_id,s.course_id) effective_course,coalesce(e.start_time,s.start_time) effective_start,coalesce(e.end_time,s.end_time) effective_end,coalesce(e.location,s.location) effective_location,coalesce(e.version,0) exception_version
 from public.weekly_schedule_slots s join dates d on extract(isodow from d.occurrence_day)=s.weekday and d.occurrence_day>=s.starts_on left join public.schedule_exceptions e on e.slot_id=s.id and e.day=d.occurrence_day where s.group_id=p_group
 ), entries as (
 select b.id,b.group_id,b.course_id,b.kind,b.title,b.body,b.location,b.starts_at,b.ends_at,p.full_name author_name,b.created_at,public.write_group_board(b.group_id,b.course_id,b.kind,b.author_id) can_manage,null::uuid template_id,null::date occurrence_date,false cancelled,0 version
 from public.group_board b join public.profiles p on p.id=b.author_id where b.group_id=p_group and b.kind='schedule' and public.read_group_board(b.group_id,b.course_id,'schedule')
 union all
 select md5(o.id::text||o.occurrence_day::text)::uuid,o.group_id,o.effective_course,'schedule',c.title,case when coalesce(o.cancelled,false) then 'Занятие отменено' else '' end,o.effective_location,(o.occurrence_day+o.effective_start) at time zone 'Asia/Bishkek',(o.occurrence_day+o.effective_end) at time zone 'Asia/Bishkek',p.full_name,o.created_at,public.write_group_board(o.group_id,o.course_id,'schedule'),o.id,o.occurrence_day,coalesce(o.cancelled,false),o.exception_version
 from occurrences o join public.courses c on c.id=o.effective_course and not c.archived join public.courses original on original.id=o.course_id and not original.archived join public.profiles p on p.id=o.author_id where public.read_group_board(o.group_id,o.course_id,'schedule') and public.read_group_board(o.group_id,o.effective_course,'schedule')
 )select * from entries where ends_at>p_from and starts_at<p_to;
$$;
create or replace function public.schedule_catalog(p_group uuid,p_from timestamptz,p_to timestamptz,p_offset integer default 0)
returns table(id uuid,group_id uuid,course_id uuid,kind text,title text,body text,location text,starts_at timestamptz,ends_at timestamptz,author_name text,created_at timestamptz,can_manage boolean,template_id uuid,occurrence_date date,cancelled boolean,version integer) language plpgsql stable security definer set search_path=pg_catalog as $$
begin
 if p_from is null or p_to is null or p_to<=p_from or p_to-p_from>interval '370 days' then raise exception 'Invalid schedule window';end if;
 return query select r.* from public.schedule_rows(p_group,p_from,p_to) r order by r.starts_at,r.created_at desc,r.id limit 50 offset greatest(0,least(coalesce(p_offset,0),100000));
end $$;
create or replace function public.save_schedule_exception(p_slot uuid,p_date date,p_cancelled boolean,p_course uuid,p_start time,p_end time,p_location text,p_version integer,p_reset boolean default false) returns void
language plpgsql security definer set search_path=pg_catalog as $$
declare slot public.weekly_schedule_slots;current_version integer;from_at timestamptz;to_at timestamptz;
begin
 select * into slot from public.weekly_schedule_slots where id=p_slot;
 if not found or not public.write_group_board(slot.group_id,slot.course_id,'schedule') then raise exception 'Schedule management denied';end if;
 perform 1 from public.weekly_schedule_days where group_id=slot.group_id and weekday=slot.weekday for update;
 if p_date is null or extract(isodow from p_date)<>slot.weekday or p_date<slot.starts_on then raise exception 'Invalid occurrence date';end if;
 select coalesce((select version from public.schedule_exceptions where slot_id=p_slot and day=p_date),0) into current_version;
 if p_version is distinct from current_version then raise exception 'Schedule changed. Refresh before saving';end if;
 if p_reset then delete from public.schedule_exceptions where slot_id=p_slot and day=p_date;else
  if p_cancelled is null or p_start is null or p_end is null or p_end<=p_start or p_location is null or length(p_location)>200 or not exists(select 1 from public.courses where id=p_course and group_id=slot.group_id and not archived) then raise exception 'Invalid lesson';end if;
  from_at:=(p_date+p_start) at time zone 'Asia/Bishkek';to_at:=(p_date+p_end) at time zone 'Asia/Bishkek';
  if not p_cancelled and exists(select 1 from public.schedule_rows(slot.group_id,(p_date::timestamp at time zone 'Asia/Bishkek'),((p_date+1)::timestamp at time zone 'Asia/Bishkek')) where template_id is distinct from p_slot and not cancelled and starts_at<to_at and ends_at>from_at) then raise exception 'Lessons overlap or invalid time';end if;
  insert into public.schedule_exceptions(slot_id,day,cancelled,course_id,start_time,end_time,location,version) values(p_slot,p_date,p_cancelled,p_course,p_start,p_end,p_location,current_version+1) on conflict(slot_id,day) do update set cancelled=excluded.cancelled,course_id=excluded.course_id,start_time=excluded.start_time,end_time=excluded.end_time,location=excluded.location,version=excluded.version;
 end if;
 if p_reset and exists(with entries as(select * from public.schedule_rows(slot.group_id,p_date::timestamp at time zone 'Asia/Bishkek',(p_date+1)::timestamp at time zone 'Asia/Bishkek')) select 1 from entries a join entries b on a.starts_at<b.ends_at and a.ends_at>b.starts_at where a.template_id=p_slot and b.template_id is distinct from p_slot and not a.cancelled and not b.cancelled) then raise exception 'Lessons overlap or invalid time';end if;
 insert into public.audit_events(actor_id,action,entity_id,details) values(auth.uid(),'schedule.exception.saved',p_slot,jsonb_build_object('date',p_date,'reset',p_reset));
end $$;
revoke all on function public.weekly_schedule_day(uuid,integer),public.save_weekly_schedule(uuid,integer,jsonb,integer,uuid),public.schedule_rows(uuid,timestamptz,timestamptz),public.schedule_catalog(uuid,timestamptz,timestamptz,integer),public.save_schedule_exception(uuid,date,boolean,uuid,time,time,text,integer,boolean) from public,anon,authenticated;
grant execute on function public.weekly_schedule_day(uuid,integer),public.save_weekly_schedule(uuid,integer,jsonb,integer,uuid),public.schedule_catalog(uuid,timestamptz,timestamptz,integer),public.save_schedule_exception(uuid,date,boolean,uuid,time,time,text,integer,boolean) to authenticated;
commit;
